/// <summary>
/// Data contract for Standard cost version generation and claim lines generation
/// </summary>
[DataContract]
internal final class METStandardCostProcessContract 
{
    NoYesId   generateClaimLines;

}

Method.Source:
/// <summary>
/// Contract member indicates whether to generate claim lines for standard cost version
/// </summary>
/// <param name = "_generateClaimLines">Generate claim lines parameter</param>
/// <returns>Generate claim lines parameter</returns>
[DataMemberAttribute, SysOperationLabelAttribute("@MET:GenerateStdCostClaimLines")]
public NoYesId parmGenerateClaimLines(NoYesId _generateClaimLines = generateClaimLines)
{
    generateClaimLines = generateClaimLines;
    return generateClaimLines;
}
